import{_ as e,C as t,c as r,o as i,j as n,G as l,b as d,a0 as a,a as s,w as o,a1 as g}from"./chunks/framework.DKRgXLPU.js";const p=JSON.parse('{"title":"Oprettelse af din træningsplan","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/goals/planning.md","filePath":"da/education/goals/planning.md"}');const u=e({name:"da/education/goals/planning.md"},[["render",function(e,p,u,m,f,k){const h=t("AdBanner"),v=t("Mermaid"),b=t("AdInArticle");return i(),r("div",null,[p[1]||(p[1]=n("h1",{id:"oprettelse-af-din-træningsplan",tabindex:"-1"},[s("Oprettelse af din træningsplan "),n("a",{class:"header-anchor",href:"#oprettelse-af-din-træningsplan","aria-label":'Permalink to "Oprettelse af din træningsplan"'},"​")],-1)),l(h),p[2]||(p[2]=n("p",null,"Mål uden en plan er blot ønsker. Denne guide hjælper dig med at forvandle dine mål til en struktureret træningsplan, der rent faktisk virker.",-1)),p[3]||(p[3]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Den store idé"),n("p",null,[n("strong",null,"Mål uden en plan er blot ønsker."),s(" En struktureret træningsplan omdanner dine mål til daglige handlinger, der resulterer i reel fremgang.")])],-1)),(i(),d(g,null,{default:o(()=>[l(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BM%C3%A5l%5D%20--%3E%20B%5BTr%C3%A6ningsplan%5D%0A%20%20%20%20B%20--%3E%20C%5BDaglige%20handlinger%5D%0A%20%20%20%20C%20--%3E%20D%5BKonsekvent%20praksis%5D%0A%20%20%20%20D%20--%3E%20E%5BM%C3%A5lbar%20fremgang%5D%0A%20%20%20%20E%20--%3E%20F%5BM%C3%A5lopfyldelse%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...p[0]||(p[0]=[s(" Loading... ",-1)])]),_:1})),p[4]||(p[4]=a('<h2 id="de-8-faser-af-selvstyret-udvikling" tabindex="-1">De 8 faser af selvstyret udvikling <a class="header-anchor" href="#de-8-faser-af-selvstyret-udvikling" aria-label="Permalink to &quot;De 8 faser af selvstyret udvikling&quot;">​</a></h2><h3 id="fase-1-sæt-dit-kompas-mal" tabindex="-1">Fase 1: Sæt dit kompas (mål) <a class="header-anchor" href="#fase-1-sæt-dit-kompas-mal" aria-label="Permalink to &quot;Fase 1: Sæt dit kompas (mål)&quot;">​</a></h3><p>Du har allerede lært om SMART-mål. Sæt dem nu i et hierarki:</p><ol><li><strong>Langsigtet mål</strong> (1-2 år): Din drøm</li><li><strong>Årligt mål</strong>: Årets mål</li><li><strong>Kvartalsvise mål</strong>: 3-måneders milepæle</li><li><strong>Månedlige mål</strong>: Specifikke fokusområder</li><li><strong>Ugentlige mål</strong>: Træningsmål</li></ol><h3 id="fase-2-vurder-dine-ressourcer" tabindex="-1">Fase 2: Vurder dine ressourcer <a class="header-anchor" href="#fase-2-vurder-dine-ressourcer" aria-label="Permalink to &quot;Fase 2: Vurder dine ressourcer&quot;">​</a></h3><p>Før du planlægger, så vurder ærligt, hvad du har:</p><table tabindex="0"><thead><tr><th>Ressource</th><th>Spørgsmål at stille</th></tr></thead><tbody><tr><td><strong>Tid</strong></td><td>Hvor mange timer om ugen kan du realistisk set træne?</td></tr><tr><td><strong>Beliggenhed</strong></td><td>Har du adgang til en ordentlig piste? Hvad er kvaliteten af underlaget?</td></tr><tr><td><strong>Udstyr</strong></td><td>Har du passende boules? Måleværktøjer? Videofunktion?</td></tr><tr><td><strong>Viden</strong></td><td>Hvad er dine tekniske styrker og svagheder?</td></tr><tr><td><strong>Fysisk tilstand</strong></td><td>Er der nogen begrænsninger? Er der områder, der skal arbejdes med?</td></tr></tbody></table><p>Vær ærlig. En realistisk plan slår en ambitiøs fantasi.</p><h3 id="fase-3-vælg-dine-øvelser" tabindex="-1">Fase 3: Vælg dine øvelser <a class="header-anchor" href="#fase-3-vælg-dine-øvelser" aria-label="Permalink to &quot;Fase 3: Vælg dine øvelser&quot;">​</a></h3><p>Vælg øvelser, der direkte understøtter dine mål:</p><p><strong>Til forbedring af pointgivning:</strong></p><ul><li>Præcisions pegning mod markerede zoner</li><li>Distancevariationsøvelser</li><li>Forskellig overfladepraksis</li></ul><p><strong>Til forbedring af skydning:</strong></p><ul><li>Skydestige (progressive distancer)</li><li>Forhindringsskydning (tvungen høj bue)</li><li>Øvelse i bevægelsesmål</li></ul><p><strong>Til mental udvikling:</strong></p><ul><li>Rutinemæssig træning før skud</li><li>Visualiseringssessioner</li><li>Tryksimulering</li></ul><p><strong>Balancer dit program:</strong></p><ul><li>Teknisk arbejde (pege, skyde)</li><li>Mental træning (mindfulness, visualisering)</li><li>Fysisk konditionering (balance, fleksibilitet)</li><li>Matchspil (anvendelse af færdigheder)</li></ul><h3 id="fase-4-opret-din-tidsplan" tabindex="-1">Fase 4: Opret din tidsplan <a class="header-anchor" href="#fase-4-opret-din-tidsplan" aria-label="Permalink to &quot;Fase 4: Opret din tidsplan&quot;">​</a></h3><p>Lav en realistisk ugentlig plan:</p>',20)),l(b),p[5]||(p[5]=a('<table tabindex="0"><thead><tr><th>Dag</th><th>Morgen</th><th>Eftermiddag</th><th>Aften</th><th>Fokus</th></tr></thead><tbody><tr><td>man</td><td>-</td><td>Teknisk: Pegning</td><td>Let mobilitet</td><td>Præcision</td></tr><tr><td>Tirsdag</td><td>-</td><td>Teknisk: Skydning</td><td>-</td><td>Effekt/nøjagtighed</td></tr><tr><td>Ons</td><td>-</td><td>Mental træning</td><td>-</td><td>Mindfulness</td></tr><tr><td>Torsdag</td><td>-</td><td>Blandet: Spilscenarier</td><td>Let mobilitet</td><td>Anvendelse</td></tr><tr><td>Fre</td><td>-</td><td>Teknisk: Svaghed</td><td>-</td><td>Forbedring</td></tr><tr><td>Lør</td><td>Kampspil eller konkurrence</td><td>-</td><td>-</td><td>Præstation</td></tr><tr><td>Sol</td><td>Hvile</td><td>Ugentlig gennemgang</td><td>Planlægning</td><td>Genopretning</td></tr></tbody></table><p><strong>Nøgleprincipper:</strong></p><ul><li>Prioritér mental træning (den bliver ofte forsømt)</li><li>Inkluder hviledage</li><li>Balancer forskellige færdigheder</li><li>Efterlad fleksibilitet for livet</li></ul><h3 id="fase-5-forbered-dig-pa-forhindringer" tabindex="-1">Fase 5: Forbered dig på forhindringer <a class="header-anchor" href="#fase-5-forbered-dig-pa-forhindringer" aria-label="Permalink to &quot;Fase 5: Forbered dig på forhindringer&quot;">​</a></h3><p>Tingene vil gå galt. Planlæg for det.</p><table tabindex="0"><thead><tr><th>Risiko</th><th>Sandsynlighed</th><th>Indvirkning</th><th>Backupplan</th></tr></thead><tbody><tr><td>Tidsmangel</td><td>Høj</td><td>Medium</td><td>Hav en &quot;minimumssession&quot; klar (20 min)</td></tr><tr><td>Dårligt vejr</td><td>Medium</td><td>Medium</td><td>Indendørs visualisering, videostudie</td></tr><tr><td>Lav motivation</td><td>Høj</td><td>Medium</td><td>Vend tilbage til &quot;hvorfor&quot;, mindre mål, tag en pause</td></tr><tr><td>Mindre skade</td><td>Medium</td><td>Høj</td><td>Fokus på mental træning, ikke-påvirkede færdigheder</td></tr><tr><td>Ingen øvepartner</td><td>Medium</td><td>Lav</td><td>Soloøvelser, video selvanalyse</td></tr></tbody></table><h3 id="fase-6-spor-dine-fremskridt" tabindex="-1">Fase 6: Spor dine fremskridt <a class="header-anchor" href="#fase-6-spor-dine-fremskridt" aria-label="Permalink to &quot;Fase 6: Spor dine fremskridt&quot;">​</a></h3><p>Det, der måles, bliver styret.</p><p><strong>Før en træningsdagbog:</strong></p><ul><li>Dato og varighed</li><li>Øvelser gennemført</li><li>Scorer/resultater</li><li>Hvordan du havde det (energi, fokus, flow)</li><li>Tekniske noter</li><li>Vejr/forhold</li></ul><p><strong>Ugentlige opfølgningsspørgsmål:</strong></p><ul><li>Fik jeg gennemført mine planlagte sessioner?</li><li>Hvilke scorer opnåede jeg?</li><li>Hvad føltes godt? Hvad var svært?</li><li>Nogle flow-erfaringer?</li><li>Hvad skal jeg justere?</li></ul><h3 id="fase-7-forbliv-motiveret" tabindex="-1">Fase 7: Forbliv motiveret <a class="header-anchor" href="#fase-7-forbliv-motiveret" aria-label="Permalink to &quot;Fase 7: Forbliv motiveret&quot;">​</a></h3><p>Motivation svinger. Byg systemer til at vedligeholde den:</p><p><strong>Intern motivation:</strong></p><ul><li>Forbind dig med dit &quot;hvorfor&quot;</li><li>Fejr små sejre</li><li>Bemærk forbedring over tid</li><li>Find glæde i processen</li></ul><p><strong>Ekstern support:</strong></p><ul><li>Træningspartnere (selv lejlighedsvis)</li><li>Del mål med nogen</li><li>Deltag i onlinefællesskaber</li><li>Sporstriber og konsistens</li></ul><p><strong>Når motivationen falder:</strong></p><ul><li>Lav en minimumssession (noget slår intet)</li><li>Ændr dine omgivelser</li><li>Gennemgå dine fremskridt</li><li>Husk tidligere succeser</li><li>Tag en planlagt pause, hvis det er nødvendigt</li></ul><h3 id="fase-8-gennemgang-og-tilpasning" tabindex="-1">Fase 8: Gennemgang og tilpasning <a class="header-anchor" href="#fase-8-gennemgang-og-tilpasning" aria-label="Permalink to &quot;Fase 8: Gennemgang og tilpasning&quot;">​</a></h3><p>Din plan bør udvikle sig:</p><p><strong>Ugentligt:</strong> Hurtig gennemgang, mindre justeringer <strong>Månedligt:</strong> Vurder fremskridt i forhold til månedlige mål, juster fokus <strong>Kvartalsvis:</strong> Stor gennemgang, fastsættelse af mål for næste kvartal <strong>Årligt:</strong> Fuld vurdering, ny årsplan</p><p><strong>Spørgsmål til gennemgang:</strong></p><ul><li>Gør jeg fremskridt i retning af mine mål?</li><li>Er min træning effektiv?</li><li>Har jeg brug for forskellige øvelser?</li><li>Er mine mål stadig relevante?</li><li>Hvad har jeg lært?</li></ul><h2 id="eksempel-pa-8-ugers-plan" tabindex="-1">Eksempel på 8-ugers plan <a class="header-anchor" href="#eksempel-pa-8-ugers-plan" aria-label="Permalink to &quot;Eksempel på 8-ugers plan&quot;">​</a></h2><p><strong>Mål:</strong> Forbedre skudpræcisionen med 15%</p><table tabindex="0"><thead><tr><th>Uge</th><th>Fokus</th><th>Nøglesessioner</th></tr></thead><tbody><tr><td>1</td><td>Basislinje</td><td>Test af strømniveau, videoanalyse</td></tr><tr><td>2</td><td>Teknik</td><td>Identificer og arbejd med centrale problemstillinger</td></tr><tr><td>3</td><td>Gentagelse</td><td>Træning med høj volumen af skydning</td></tr><tr><td>4</td><td>Prøve</td><td>Midtvejsevaluering, juster</td></tr><tr><td>5</td><td>Variation</td><td>Forskellige afstande og vinkler</td></tr><tr><td>6</td><td>Tryk</td><td>Tilføj konsekvenser til øvelser</td></tr><tr><td>7</td><td>Integration</td><td>Spillignende scenarier</td></tr><tr><td>8</td><td>Slutprøve</td><td>Mål forbedring</td></tr></tbody></table><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>Planlæg dit arbejde, og arbejd derefter på din plan. Men vær forberedt på at tilpasse dig.</p></blockquote><p>Den bedste plan er en, du rent faktisk følger. Start simpelt, vær konsekvent, og juster, efterhånden som du lærer.</p>',31)),l(h)])}]]);export{p as __pageData,u as default};
